#include "Trust.h"

#include <CommonCrypto/CommonDigest.h>
#include <Security/Security.h>

#include <algorithm>
#include <cstring>

// Generated by src/update/update.cmake from src/update/keys/*.pub.pem: one raw string
// literal per committed PEM file, `releaseKeyFiles`.
#include "tubamp_update_release_keys.inc"

namespace tubamp::update::detail
{
namespace
{
    // DER prefix of a SubjectPublicKeyInfo for id-ecPublicKey on prime256v1 with an
    // uncompressed point: everything before the 65 point bytes.
    constexpr std::uint8_t p256SpkiPrefix[] = {
        0x30, 0x59, 0x30, 0x13, 0x06, 0x07, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x02, 0x01,
        0x06, 0x08, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x03, 0x01, 0x07, 0x03, 0x42, 0x00,
    };

    template <class T>
    struct CFOwned
    {
        T ref = nullptr;
        ~CFOwned() { if (ref != nullptr) CFRelease (ref); }
    };

    CFDataRef makeData (ByteView b)
    {
        return CFDataCreate (kCFAllocatorDefault, b.data(), CFIndex (b.size()));
    }

    SecKeyRef makePublicKey (const TrustedKey& key)
    {
        const void* names[] = { kSecAttrKeyType, kSecAttrKeyClass };
        const void* values[] = { kSecAttrKeyTypeECSECPrimeRandom, kSecAttrKeyClassPublic };
        CFOwned<CFDictionaryRef> attributes { CFDictionaryCreate (kCFAllocatorDefault, names, values, 2,
                                                                  &kCFTypeDictionaryKeyCallBacks,
                                                                  &kCFTypeDictionaryValueCallBacks) };
        CFOwned<CFDataRef> data { makeData (key.point) };
        return SecKeyCreateWithData (data.ref, attributes.ref, nullptr);
    }

    bool verifies (const TrustedKey& key, ByteView message, ByteView der)
    {
        CFOwned<SecKeyRef> secKey { makePublicKey (key) };
        if (secKey.ref == nullptr)
            return false;
        CFOwned<CFDataRef> msg { makeData (message) };
        CFOwned<CFDataRef> sig { makeData (der) };
        return SecKeyVerifySignature (secKey.ref, kSecKeyAlgorithmECDSASignatureMessageX962SHA256,
                                      msg.ref, sig.ref, nullptr);
    }

    std::vector<TrustedKey> parseReleaseKeys()
    {
        std::vector<TrustedKey> keys;
        for (const auto& file : releaseKeyFiles)
            if (auto key = parsePublicKeyPem (file.pem))
                keys.push_back (*key);
        return keys;
    }
}

KeyId keyIdOf (const TrustedKey& key) noexcept
{
    const auto digest = sha256 (key.point);
    KeyId id {};
    std::copy_n (digest.begin(), id.size(), id.begin());
    return id;
}

std::optional<TrustedKey> parsePublicKeyPem (std::string_view pem)
{
    constexpr std::string_view begin = "-----BEGIN PUBLIC KEY-----", end = "-----END PUBLIC KEY-----";
    const auto b = pem.find (begin);
    const auto e = pem.find (end);
    if (b == std::string_view::npos || e == std::string_view::npos || e < b)
        return std::nullopt;

    std::string body;
    for (char c : pem.substr (b + begin.size(), e - b - begin.size()))
        if (c != '\n' && c != '\r')
            body += c;

    const auto der = decodeBase64 (body);
    if (! der || der->size() != sizeof (p256SpkiPrefix) + 65
        || ! std::equal (std::begin (p256SpkiPrefix), std::end (p256SpkiPrefix), der->begin()))
        return std::nullopt;

    TrustedKey key;
    std::copy (der->begin() + std::ptrdiff_t (sizeof (p256SpkiPrefix)), der->end(), key.point.begin());

    CFOwned<SecKeyRef> onCurve { makePublicKey (key) };
    if (key.point[0] != 0x04 || onCurve.ref == nullptr)
        return std::nullopt;
    return key;
}

const TrustRoot& TrustRoot::release()
{
    static const TrustRoot root (parseReleaseKeys());
    return root;
}

TrustRoot::TrustRoot (std::vector<TrustedKey> keys) : trusted (std::move (keys)) {}

Result<VerifiedPayload, SignatureError> TrustRoot::verify (const SignedEnvelope& envelope) const
{
    const auto message = envelope.signedMessage();
    bool anyVerified = false;

    for (const auto& sig : envelope.signatures())
    {
        const auto key = std::find_if (trusted.begin(), trusted.end(),
                                       [&] (const TrustedKey& k) { return keyIdOf (k) == sig.key; });
        if (key == trusted.end())
            continue;
        if (! verifies (*key, message, sig.der))
            return SignatureError::invalid;
        anyVerified = true;
    }

    if (! anyVerified)
        return SignatureError::unknownKey;
    const auto payload = envelope.payload();
    return VerifiedPayload (Bytes (payload.begin(), payload.end()));
}

static_assert (sizeof (CC_SHA256_CTX) <= 128);

Sha256Stream::Sha256Stream() noexcept
{
    CC_SHA256_Init (reinterpret_cast<CC_SHA256_CTX*> (state.data()));
}

void Sha256Stream::update (ByteView bytes) noexcept
{
    auto* ctx = reinterpret_cast<CC_SHA256_CTX*> (state.data());
    // CC_SHA256_Update takes a 32-bit length.
    for (std::size_t done = 0; done < bytes.size();)
    {
        const auto n = std::min<std::size_t> (bytes.size() - done, 1u << 30);
        CC_SHA256_Update (ctx, bytes.data() + done, CC_LONG (n));
        done += n;
    }
}

Sha256 Sha256Stream::finish() noexcept
{
    Sha256 digest {};
    CC_SHA256_Final (digest.data(), reinterpret_cast<CC_SHA256_CTX*> (state.data()));
    return digest;
}

Sha256 sha256 (ByteView bytes) noexcept
{
    Sha256Stream stream;
    stream.update (bytes);
    return stream.finish();
}

Result<Manifest, Refusal> openEnvelope (ByteView file, const TrustRoot& trust)
{
    auto envelope = SignedEnvelope::split (file);
    if (! envelope)
        return Refusal (envelope.error());
    auto payload = trust.verify (envelope.value());
    if (! payload)
        return Refusal (payload.error());
    auto manifest = parseManifest (payload.value());
    if (! manifest)
        return Refusal (manifest.error());
    return std::move (manifest).value();
}

bool codeSealIntact (const std::filesystem::path& bundle)
{
    const auto& text = bundle.native();
    CFOwned<CFURLRef> url { CFURLCreateFromFileSystemRepresentation (
        kCFAllocatorDefault, reinterpret_cast<const UInt8*> (text.data()), CFIndex (text.size()), true) };
    SecStaticCodeRef code = nullptr;
    if (url.ref == nullptr || SecStaticCodeCreateWithPath (url.ref, kSecCSDefaultFlags, &code) != errSecSuccess)
        return false;
    CFOwned<SecStaticCodeRef> owned { code };
    return SecStaticCodeCheckValidity (code, kSecCSCheckAllArchitectures | kSecCSStrictValidate, nullptr)
        == errSecSuccess;
}
} // namespace tubamp::update::detail
